/**
 * diagnosis/category-clarity.ts — 品类认知清晰度
 *
 * 核心问题：客户用同一个品类词描述公司吗？
 *
 * 纯代码模块，零 LLM 调用。基于客户访谈文本的词频统计：
 *   - >70% 客户用同一品类词 → "品类认知清晰"
 *   - 30-70% → "模糊，需要强化"
 *   - <30% → "品类认知混乱"
 *
 * 理论支撑：定位理论——消费者用"品类"思考，用"品牌"表达。
 * 心智中的信息以"品类阶梯"的形式组织。
 *
 * 关联: ARCH-19 §3.1、positioning-consistency.ts
 */
export interface CategoryClarityResult {
    /** 主导品类词 */
    dominantCategory: string | null;
    /** 使用主导词的客户比例 0-1 */
    consistencyRatio: number;
    /** 判定级别 */
    clarity: 'clear' | 'fuzzy' | 'chaotic';
    /** 各品类词及其出现频次 */
    categoryDistribution: Array<{
        term: string;
        count: number;
        pct: number;
    }>;
    /** 客户原话样本（脱敏，最多5条） */
    sampleQuotes: string[];
    /** 总样本数 */
    totalResponses: number;
    /** 解读 */
    interpretation: string;
}
/**
 * Compute category clarity from customer interview responses.
 *
 * @param responses - Array of customer responses to "what word comes to mind
 *   when you think of our company?" or similar category-probing questions.
 *   Each string is one customer's full response.
 * @returns CategoryClarityResult or null if insufficient data.
 */
export declare function computeCategoryClarity(responses: string[]): CategoryClarityResult | null;
/**
 * Compute category clarity from stored survey responses for a team.
 * Wraps computeCategoryClarity with data loading.
 */
export declare function computeCategoryClarityForTeam(teamId: string, responses?: string[]): Promise<CategoryClarityResult | null>;
